import random, sys
sys.path.insert(0, '/workspace/project')
NAMES = ('allreduce', 'reduce', 'broadcast', 'barrier', 'allgather', 'reducescatter')


def gen_case(rng, big=False):
    pr = rng.choice(NAMES)
    if pr == 'barrier':
        K, D = 1, 0
    else:
        K = rng.choice([1, 2, 3, 4, 5, 6, 7, 8, 12, 16]) if not big else rng.choice([1, 4, 8, 16, 32])
        if pr == 'reducescatter':
            K = rng.choice([4, 8, 12, 16])
        D = 0 if pr == 'barrier' else rng.choice([1, 2, 3, 5])
    mode = rng.choice([2, 3])
    root = rng.randrange(4)
    N = rng.choice([1, 2, 3, K, K + 1, 2 * K, 40]) if K > 1 else rng.choice([1, 2, 3])
    N = max(1, min(N, 64))
    wrap = rng.random() < 0.35
    start = rng.randrange((1 << 24) - 3 * K - 4, (1 << 24)) if wrap else rng.randrange(0, 1000)
    events = []
    n_events = rng.randrange(0, 14 if not big else 8)
    for _ in range(n_events):
        kind = rng.choices(['data', 'ack', 'wire', 'budget', 'flush', 'retry', 'snap', 'train'],
                           weights=[30, 18, 8, 5, 8, 8, 5, 6])[0]
        if kind == 'data':
            op = {'op': 'data', 'rank': rng.randrange(4), 'p': rng.randrange(K)}
            if rng.random() < 0.3:
                op['count'] = rng.randrange(1, 4)
                op['step'] = rng.choice([0, 1, 2, -1, K])
            if rng.random() < 0.25:
                op['values'] = [rng.randrange(0, 1 << 32) for _ in range(D)]
            if rng.random() < 0.25:
                op['seed'] = rng.randrange(0, 1 << 32)
            if rng.random() < 0.2:
                op['xor'] = [[rng.randrange(0, 58 + 4 * D), rng.randrange(0, 256)]
                             for _ in range(rng.randrange(1, 4))]
            if 'values' in op and 'count' in op:
                del op['count']
            events.append(op)
        elif kind == 'ack':
            events.append({'op': 'ack', 'rank': rng.randrange(4),
                           'upto': rng.choice([0, 1, rng.randrange(0, 3 * K + 2),
                                               rng.randrange(0, 3 * K + 2)])})
        elif kind == 'wire':
            length = rng.choice([0, rng.randrange(0, 40), rng.randrange(0, 130)])
            events.append({'op': 'wire', 'rank': rng.randrange(4),
                           'hex': bytes(rng.randrange(256) for _ in range(length)).hex()})
        elif kind == 'budget':
            events.append({'op': 'budget', 'n': rng.choice([-1, 0, 1, 2, 3, rng.randrange(0, 6)])})
        elif kind == 'flush':
            events.append({'op': 'flush'})
        elif kind == 'retry':
            events.append({'op': 'retry', 'rank': rng.randrange(4)})
        elif kind == 'snap':
            events.append({'op': 'snap', 'tag': 't%d' % rng.randrange(100)})
        else:
            count = rng.randrange(1, min(K, 6) + 1)
            op = {'op': 'train', 'p': rng.randrange(0, K - count + 1), 'count': count,
                  'width': rng.randrange(1, min(N, K) + 1),
                  'ranks': rng.sample(range(4), 4)}
            if rng.random() < 0.3:
                op['reverse'] = rng.choice([True, False])
            if rng.random() < 0.4:
                op['seed'] = rng.randrange(0, 1 << 32)
            events.append(op)
    case = {'primitive': pr, 'mode': mode, 'root': root, 'segments': K, 'words': D,
            'capacity': N, 'start': start, 'events': events}
    if rng.random() < 0.4:
        case['trace'] = rng.randrange(0, 6)
    return case
