import json, random, sys, time
from pathlib import Path
sys.path.insert(0, '/workspace/project')
sys.path.insert(0, '/tmp/fuzz')
import solver, ref, gen

here = Path('/workspace/project')
lib = solver.load_library(here, Path('/tmp'))
solver.bind(lib)

def compare(case, got, want):
    diffs = []
    for key in ('state', 'buffer', 'wire_sha256', 'packets', 'bytes'):
        if got[key] != want[key]:
            diffs.append((key, got[key], want[key]))
    if len(got['snapshots']) != len(want['snapshots']):
        diffs.append(('snapcount', len(got['snapshots']), len(want['snapshots'])))
    else:
        for i, (a, b) in enumerate(zip(got['snapshots'], want['snapshots'])):
            if a != b:
                diffs.append(('snap%d' % i, a, b))
    if got['trace'] != want['trace']:
        diffs.append(('trace', got['trace'], want['trace']))
    return diffs

trials = int(sys.argv[1]) if len(sys.argv) > 1 else 200
seed0 = int(sys.argv[2]) if len(sys.argv) > 2 else 12345
bad = 0
t0 = time.time()
for t in range(trials):
    rng = random.Random(seed0 + t)
    case = gen.gen_case(rng)
    try:
        want = ref.solve_case(case)
    except Exception as exc:
        print('REF ERROR', t, exc, json.dumps(case)); bad += 1; continue
    got = solver.replay(case, lib)
    diffs = compare(case, got, want)
    if diffs:
        bad += 1
        print('=== MISMATCH trial', t)
        print(json.dumps(case))
        for d in diffs[:4]:
            print('  ', d[0], 'got ', d[1])
            print('  ', d[0], 'want', d[2])
        if bad >= 3:
            break
print('trials', trials, 'bad', bad, 'secs', round(time.time() - t0, 1))
PYEOF
